import crypto from 'node:crypto';
export const UBUDDY_DEPENDENCY_BUNDLE_VERSION='ubuddy_dependency_bundle_v1';
export const DEPENDENCY_DIMENSIONS=Object.freeze(['data','logic','quality','freshness','review','capability','resource','risk','downstreamImpact','uncertainty']);
export const DEPENDENCY_EVENT_TYPES=Object.freeze(['publish','consume','review','timeout','retry','handoff','versionChange','resourceChange','failure','result_published','output_published','memory_published','result_consumed','review_passed','review_failed','quality_review_failed','result_expired','requirement_changed','capability_snapshot','resource_update','dependency_updated','result_superseded']);
const STATUSES=new Set(['unknown','unavailable','available','stale','invalidated','satisfied','partially_satisfied','pending','passed','failed','fresh','expired','matched','mismatched','ready','degraded','offline']);
export function clampScore(value,fallback=0){const n=Number(value);return Number.isFinite(n)?Math.max(0,Math.min(1,n)):fallback;}
export function normalizeEvidenceRefs(refs){return [...new Set((Array.isArray(refs)?refs:refs?[refs]:[]).map(v=>String(v||'').trim()).filter(Boolean))].slice(0,100);}
export function normalizeDependencyBundle(bundle={}){const dimensions={};for(const key of DEPENDENCY_DIMENSIONS){const raw=bundle[key]&&typeof bundle[key]==='object'?bundle[key]:{};const item={...raw};for(const sk of ['score','matchScore','impactScore'])if(sk in item)item[sk]=clampScore(item[sk]);if('status' in item){const s=String(item.status||'').trim().toLowerCase();item.status=STATUSES.has(s)?s:'unknown';}item.explanation=String(item.explanation||'').replace(/\s+/g,' ').trim().slice(0,1000);item.evidenceRefs=normalizeEvidenceRefs(item.evidenceRefs);dimensions[key]=item;}const n={version:String(bundle.version||UBUDDY_DEPENDENCY_BUNDLE_VERSION),bundleVersionId:String(bundle.bundleVersionId||'').trim(),taskId:String(bundle.taskId||'').trim(),taskRunId:String(bundle.taskRunId||'').trim(),edgeId:String(bundle.edgeId||'').trim(),sourceNode:bundle.sourceNode||bundle.fromNodeId||'',targetNode:bundle.targetNode||bundle.toNodeId||'',sourceAgent:bundle.sourceAgent||'',targetAgent:bundle.targetAgent||'',relationType:String(bundle.relationType||'').trim(),fromNodeId:String(bundle.fromNodeId||bundle.sourceNode?.nodeId||'').trim(),toNodeId:String(bundle.toNodeId||bundle.targetNode?.nodeId||'').trim(),versionNo:Math.max(1,Number(bundle.versionNo||1)),trigger:String(bundle.trigger||'initial').trim(),lifecycle:String(bundle.lifecycle||'TDB-plan').trim(),eventId:String(bundle.eventId||'').trim(),updatedAt:String(bundle.updatedAt||new Date().toISOString()).trim(),latestResultVersionId:String(bundle.latestResultVersionId||'').trim(),...dimensions,stateVector:dimensions,workMemoryRefs:normalizeEvidenceRefs(bundle.workMemoryRefs),consumedResultVersionIds:normalizeEvidenceRefs(bundle.consumedResultVersionIds),evidenceRefs:normalizeEvidenceRefs(bundle.evidenceRefs),trace:Array.isArray(bundle.trace)?bundle.trace.slice(-100):[]};if(!n.bundleVersionId)n.bundleVersionId=dependencyBundleVersionId(n);return n;}
export function dependencyBundleVersionId(bundle={}){const copy={...bundle,bundleVersionId:'',updatedAt:''};return 'dep_bundle_'+crypto.createHash('sha256').update(JSON.stringify(copy)).digest('hex').slice(0,24);}
export function validateDependencyBundle(bundle={}){const b=normalizeDependencyBundle(bundle),errors=[];if(b.version!==UBUDDY_DEPENDENCY_BUNDLE_VERSION)errors.push('invalid_version');if(!b.edgeId||!b.fromNodeId||!b.toNodeId)errors.push('edge_and_nodes_required');if(!Number.isInteger(b.versionNo)||b.versionNo<1)errors.push('invalid_version_no');for(const k of DEPENDENCY_DIMENSIONS){const raw=bundle[k]&&typeof bundle[k]==='object'?bundle[k]:{};for(const sk of ['score','matchScore','impactScore'])if(sk in raw&&(!Number.isFinite(Number(raw[sk]))||Number(raw[sk])<0||Number(raw[sk])>1))errors.push(k+'_'+sk);}return {valid:errors.length===0,errors,bundle:b};}
export function dependencyBundleEventType(event={}){const raw=String(event.type||event.eventType||event.kind||'').trim().toLowerCase();return DEPENDENCY_EVENT_TYPES.find((item)=>item.toLowerCase()===raw)||'dependency_updated';}
